    "result": "conn_state",
    "v7": "link_ctx",
    "v8": "link_ctx",
    "v9": "conn_ctx",
    "v10": "link_state",
    "v11": "pending_count",
    "v12": "conn_ctx"
  },
  "struct_hints": [
    {
      "offset": 1225,
      "meaning": "connection index extracted from the source message/context"
    },
    {
      "offset": 112,
      "meaning": "BT connection state byte; treated as valid/connected when equal to 1"
    },
    {
      "offset": 16,
      "meaning": "pending state-machine event flag in the per-link 48-byte subcontext"
    },
    {
      "offset": 32,
      "meaning": "secondary per-link state or event condition flag"
    },
    {
      "offset": 121,
      "meaning": "pending event or command counter"
    },
    {
      "offset": 122,
      "meaning": "secondary pending counter decremented when the link state is 1"
    },
    {
      "offset": 115,
      "meaning": "connection condition flag used when selecting the resulting event flag"
    },
    {
      "offset": 113,
      "meaning": "event or flag index byte passed to set_flag_byte"
    }
  ]
}
